source='''def transform(grid):
    cells = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 8}
    h, w = len(grid), len(grid[0]) if grid else 0
    placements = []
    # A solid 2x2 block is color 1.
    for r in range(h - 1):
        for c in range(w - 1):
            block = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if block <= cells:
                placements.append((block, 1))
            # L triominoes are colored by the missing corner.
            corner_colors = {
                (r, c): 2,          # missing top-left
                (r + 1, c): 3,      # missing bottom-left
                (r, c + 1): 4,      # missing top-right
                (r + 1, c + 1): 5,  # missing bottom-right
            }
            for missing, color in corner_colors.items():
                shape = block - {missing}
                if shape <= cells:
                    placements.append((shape, color))
    # Exact-cover the occupied cells with these pieces.
    by_cell = {cell: [] for cell in cells}
    for shape, color in placements:
        for cell in shape:
            by_cell[cell].append((shape, color))
    answer = [[0 for _ in row] for row in grid]
    def search(left):
        if not left:
            return True
        cell = min(left, key=lambda x: sum(shape <= left for shape, _ in by_cell[x]))
        for shape, color in by_cell[cell]:
            if shape <= left:
                for r, c in shape:
                    answer[r][c] = color
                if search(left - shape):
                    return True
                for r, c in shape:
                    answer[r][c] = 0
        return False
    if not search(cells):
        raise ValueError("No tiling found")
    return answer
